use vstd::prelude::*;

verus! {

    // A pure specification of bitwise XOR on bits represented as chars '0' or '1'.
    spec fn bit_xor(c1: char, c2: char) -> char
        requires
            c1 == '0' || c1 == '1',
            c2 == '0' || c2 == '1',
    {
        if c1 == c2 {
            '0'
        } else {
            '1'
        }
    }

    // Compute element‐wise XOR of two equal‐length binary strings (Vec<char>).
    fn string_xor(a: Vec<char>, b: Vec<char>) -> (res: Vec<char>)
        requires
            a.len() == b.len(),
            // All inputs are bits.
            forall |i: usize| i < a.len() ==> (a[i] == '0' || a[i] == '1'),
            forall |i: usize| i < b.len() ==> (b[i] == '0' || b[i] == '1'),
        ensures
            // Result has same length and each position is the XOR of inputs.
            res.len() == a.len() &&
            forall |i: usize| i < a.len() ==> res[i] == bit_xor(a[i], b[i]),
    {
        let n = a.len();
        let mut res: Vec<char> = Vec::with_capacity(n);
        let mut i: usize = 0;
        while i < n
            invariant
                // progress
                i <= n,
                // res has accumulated exactly i elements
                res.len() == i,
                // correctness on [0..i)
                forall |j: usize| j < i ==> res[j] == bit_xor(a[j], b[j]),
            decreases n - i
        {
            let ca = a[i];
            let cb = b[i];
            // re‐establish bit assumptions for the current elements
            assert(ca == '0' || ca == '1');
            assert(cb == '0' || cb == '1');

            let c = if ca == cb { '0' } else { '1' };
            // relate the computed c to the spec bit_xor
            assert(c == bit_xor(ca, cb));

            res.push(c);
            i += 1;
        }
        res
    }

} // verus!

